import Foundation
struct HostFailure:Error{let message:String}
@main @MainActor struct NativeNotesHostProtocolTests {
 static var count=0,failures=0
 static let client="12345678-1234-4123-8123-123456789abc"
 static let frame=NativeTaskRectangle(x:0,y:0,width:1000,height:700)
 static func check(_ value:@autoclosure()throws->Bool,_ message:String)throws{if try !value(){throw HostFailure(message:message)}}
 static func reject(_ body:()throws->Void)throws{do{try body()}catch is HostFailure{throw HostFailure(message:"assert inside rejection")}catch{return};throw HostFailure(message:"expected refusal")}
 static func run(_ name:String,_ body:()throws->Void){do{try body();count+=1;print("PASS "+name)}catch{failures+=1;print("FAIL "+name+": "+((error as? HostFailure)?.message ?? String(describing:type(of:error))))}}
 static func context()->NativeNotesHostContext{.init(owner:.init(windowID:UUID(),documentID:UUID(),contextGeneration:0),paperID:"")}
 static func metrics(_ change:[String:Any]=[:])throws->NativeNotesDOMObservation{var raw:[String:Any]=["clientID":client,"notesVisible":true,"blocked":false,"width":1000,"height":700,"main":["x":200,"y":0,"width":800,"height":700],"toolbar":["x":200,"y":0,"width":800,"height":62],"sidebarVisible":true,"sidebar":["x":0,"y":0,"width":200,"height":700],"notes":["x":200,"y":62,"width":800,"height":638]];raw.merge(change){_,new in new};return try .init(raw)}
 static func bootstrap(_ c:NativeNotesHostCoordinator)throws->String{try c.bootstrap(client:client,paperID:c.context.paperID,observedClient:client,current:c.context)["nonce"] as! String}
 static func request(_ nonce:String,_ seq:Int64=1,notes:Bool=true,change:[String:Any]=[:])throws->NativeNotesPresentRequest{var raw:[String:Any]=["nonce":nonce,"clientID":client,"paperID":"","sequence":seq,"notes":notes,"focus":false];raw.merge(change){_,new in new};return try .init(raw)}
 static func ready(_ c:NativeNotesHostCoordinator,_ n:String,seq:Int64=1)throws->NativeNotesHostTicket{let t=try c.reserve(request(n,seq),current:c.context);_ = try c.finish(t,current:c.context,observation:metrics(),nativeFrame:frame,pageZoom:1);return t}
 static func main(){
  run("only actual main view top-frame fixed URL"){let u=URL(string:"paperapp://app/index.html")!;try check(NativeNotesHostCoordinator.sourceAllowed(isMainView:true,isMainFrame:true,url:u),"valid source");for (main,top,url)in [(false,true,u),(true,false,u),(true,true,URL(string:"paperapp://app/settings.html")!),(true,true,URL(string:"paperapp://app/index.html?old")!),(true,true,URL(string:"https://app/index.html")!)]{try check(!NativeNotesHostCoordinator.sourceAllowed(isMainView:main,isMainFrame:top,url:url),"foreign source")}}
  run("strict payload no arbitrary fields types") {let n=UUID().uuidString.lowercased();for change:[String:Any] in [["sequence":true],["sequence":1.5],["sequence":0],["notes":1],["focus":"yes"],["command":"model.run"]]{try reject{_ = try request(n,change:change)}}}
  run("bootstrap native nonce only same observed document") {let c=NativeNotesHostCoordinator(context:context());try reject{_ = try c.bootstrap(client:client,paperID:"",observedClient:UUID().uuidString.lowercased(),current:c.context)};try check(NativeNotesHostCoordinator.validID(bootstrap(c)),"nonce not generated")}
  run("bootstrap wrong paper or changed owner refuses") {let c=NativeNotesHostCoordinator(context:context());try reject{_ = try c.bootstrap(client:client,paperID:"other",observedClient:client,current:c.context)};try reject{_ = try c.bootstrap(client:client,paperID:"",observedClient:client,current:context())}}
  run("repeat bootstrap retains high water") {let c=NativeNotesHostCoordinator(context:context());let n=try bootstrap(c);_ = try ready(c,n,seq:8);let same=try c.bootstrap(client:client,paperID:"",observedClient:client,current:c.context);try check(same["nonce"] as? String==n && same["highestSequence"] as? Int64==8,"reset replay guard");try reject{_ = try c.reserve(request(n,8),current:c.context)}}
  run("same URL new client cannot steal existing document") {let c=NativeNotesHostCoordinator(context:context());_ = try bootstrap(c);let next=UUID().uuidString.lowercased();try reject{_ = try c.bootstrap(client:next,paperID:"",observedClient:next,current:c.context)}}
  run("wrong nonce client or paper refuses") {let c=NativeNotesHostCoordinator(context:context());let n=try bootstrap(c);for change:[String:Any] in [["nonce":UUID().uuidString.lowercased()],["clientID":UUID().uuidString.lowercased()],["paperID":"other"]]{try reject{_ = try c.reserve(request(n,change:change),current:c.context)}}}
  run("native geometry excludes sidebar and toolbar converted") {let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c);let t=try c.reserve(request(n),current:c.context);let v=try c.finish(t,current:c.context,observation:metrics(),nativeFrame:frame,pageZoom:1);try check(v?.layout.rectangle == .init(x:200,y:0,width:800,height:638),"wrong CSS to native");_ = try c.invocation()}
  run("out of band sidebar or toolbar measurement refuses") {for rect:[String:Any] in [["x":0,"y":62,"width":1000,"height":638],["x":200,"y":0,"width":800,"height":700],["x":200,"y":62,"width":801,"height":638]]{try reject{_ = try metrics(["notes":rect]).geometry(nativeFrame:frame,pageZoom:1)}}}
  run("nonfinite bool malformed viewport refused") {for change:[String:Any] in [["width":true],["width":Double.nan],["height":-1]]{try reject{_ = try metrics(change).geometry(nativeFrame:frame,pageZoom:1)}};try reject{_ = try metrics().geometry(nativeFrame:frame,pageZoom:Double.infinity)}}
  run("blocked or hidden DOM cannot show native") {for change:[String:Any] in [["blocked":true],["notesVisible":false]]{let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c),t=try c.reserve(request(n),current:c.context);try reject{_ = try c.finish(t,current:c.context,observation:metrics(change),nativeFrame:frame,pageZoom:1)};try reject{_ = try c.invocation()}}}
  run("late old measure cannot retire new accepted frame") {let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c),old=try c.reserve(request(n),current:c.context);_ = try ready(c,n,seq:2);let now=try c.invocation();try reject{_ = try c.finish(old,current:c.context,observation:metrics(),nativeFrame:frame,pageZoom:1)};try check(!c.isLatest(old,current:c.context),"old flagged latest");try c.requireCurrent(now,current:c.context)}
  run("pending new request forbids old callback") {let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n);let old=try c.invocation();_ = try c.reserve(request(n,2),current:c.context);try reject{try c.requireCurrent(old,current:c.context)}}
  run("leaving retires actual invocation") {let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n);let token=try c.invocation(),leave=try c.reserve(request(n,2,notes:false),current:c.context);try check(try c.finish(leave,current:c.context,observation:nil,nativeFrame:frame,pageZoom:1)==nil,"leave showed content");try reject{try c.requireCurrent(token,current:c.context)}}
  run("context and restore epoch change invalidate old nonce") {let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n);let old=try c.invocation();var next=c.context;next = .init(owner:.init(windowID:next.owner.windowID,documentID:next.owner.documentID,contextGeneration:1),paperID:"");c.replaceContext(next);try reject{try c.requireCurrent(old,current:c.context)};try reject{_ = try c.reserve(request(n,2),current:c.context)};let fresh=try bootstrap(c);try check(n != fresh,"reused old nonce")}
  run("same context does not reset accepted state") {let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c);_ = try ready(c,n,seq:3);let token=try c.invocation();c.replaceContext(c.context);try c.requireCurrent(token,current:c.context);try reject{_ = try c.reserve(request(n,3),current:c.context)}}
  run("changed document measurement refuses") {let c=NativeNotesHostCoordinator(context:context()),n=try bootstrap(c),t=try c.reserve(request(n),current:c.context);try reject{_ = try c.finish(t,current:c.context,observation:metrics(["clientID":UUID().uuidString.lowercased()]),nativeFrame:frame,pageZoom:1)};try reject{_ = try c.invocation()}}

  run("notes and annotation-only rows keep literal previews and no source writes") {let value:[String:Any]=["notes":["paper-A":["text":"<img src=x> 私人文字","revision":2,"updatedAt":"2026-10-27T00:00:00Z"],"blank":["text":"  ","revision":0]],"annotations":["paper-B":[["text":"原文摘录","comment":"我的批注"]]],"personalPapers":["paper-A":["id":"paper-A","title":"Original title"]]];let before=try JSONSerialization.data(withJSONObject:value,options:[.sortedKeys]);let snapshot=try NativeNotesProjection.make(value);try check(snapshot.rows.count==2,"all actual notes not projected");try check(snapshot.rows.first?.preview=="<img src=x> 私人文字" && snapshot.rows.last?.annotationCount==1,"literal or annotation changed");try check(try JSONSerialization.data(withJSONObject:value,options:[.sortedKeys])==before,"projection wrote source")}
  run("malformed notes revisions metadata ownership and source structures fail closed") {for value:[String:Any] in [["notes":[],"annotations":[:]], ["notes":["A":["text":"x","revision":true]],"annotations":[:]], ["notes":["A":["text":"x","revision":0]],"annotations":[:],"personalPapers":["A":["id":"B"]]]]{try reject{_=try NativeNotesProjection.make(value)}}}
  run("unknown metadata uses explicit original ID without author or score synthesis") {let snapshot=try NativeNotesProjection.make(["notes":["A":["text":"x","revision":0]],"annotations":[:]]);try check(snapshot.rows[0].title=="A" && snapshot.rows[0].time=="时间未知","unknown metadata fabricated")}
  run("note projection pagination retains all41 source IDs") {let notes=Dictionary(uniqueKeysWithValues:(0..<41).map{("ID-\($0)",["text":"note-\($0)","revision":0] as [String:Any])});let snapshot=try NativeNotesProjection.make(["notes":notes,"annotations":[:]]);let seen=(0..<3).flatMap{snapshot.page($0).rows.map(\.paperID)};try check(seen.count==41 && Set(seen)==Set(notes.keys),"pagination omission");try check(snapshot.page(99).index==2 && snapshot.page(-1).index==0,"page bounds")}
  run("native note lease is exact source and retired context scoped") {let c=context(),gate=NativeNotesRouteGate(owner:c.owner);try gate.accept(.init(owner:c.owner,sequence:1,notes:true,rectangle:.init(x:200,y:0,width:800,height:638)),allowed:.init(x:200,y:0,width:800,height:638));let original:[String:Any]=["notes":["A":["text":"first","revision":0]],"annotations":[:]];let snapshot=try NativeNotesProjection.make(original),lease=try gate.issue(snapshot.rows[0]);try gate.validate(lease,snapshot:snapshot);try reject{try gate.validate(lease,snapshot:NativeNotesProjection.make(["notes":["A":["text":"changed","revision":1]],"annotations":[:]]))};gate.retire();try reject{try gate.validate(lease,snapshot:snapshot)}}
  run("notes and tasks share geometry tools but never bootstrap namespace") {let task=NativeTaskHostCoordinator(context:.init(owner:context().owner,paperID:"")),notes=NativeNotesHostCoordinator(context:context());let tn=try task.bootstrap(client:client,paperID:"",observedClient:client,current:task.context)["nonce"] as! String,nn=try bootstrap(notes);try check(tn != nn,"shared nonce");try reject{_=try notes.reserve(request(tn),current:notes.context)}}
  print("RESULT \(count) passed / \(failures) failed");exit(failures==0 ? 0:1)
 }
}
